const open = useSelector((state) => state.settings.modalOpen);
const dispatch = useDispatch();

function SettingsPage() {
  return (
    <>
      <button onClick={() => dispatch(openModal())}>Settings</button>
      {open && <SettingsModal onClose={() => dispatch(closeModal())} />}
    </>
  );
